    let currentQcmIndex = 0;
    let userSelectedChoices = new Set();
    let qcmScore = 0;
    let qcmAnsweredCount = 0;

    function getActiveQcmList() {
      return (window.currentQcmFilteredList && window.currentQcmFilteredList.length > 0)
        ? window.currentQcmFilteredList
        : (window.qcmsDemoList || []);
    }

    function renderCurrentQcm() {
      const list = getActiveQcmList();
      if (!list || list.length === 0) return;

      if (currentQcmIndex >= list.length) {
        renderQcmFinished();
        return;
      }

      const q = list[currentQcmIndex];
      userSelectedChoices.clear();

      const counterEl = document.getElementById('qcmCounter');
      if (counterEl) counterEl.innerText = `Question ${currentQcmIndex + 1} sur ${list.length}`;

      const specEl = document.getElementById('qcmSpecialtyBadge');
      if (specEl) specEl.innerText = q.specialty;

      const qTextEl = document.getElementById('qcmQuestionText');
      if (qTextEl) qTextEl.innerText = q.question;

      const choicesList = document.getElementById('qcmChoicesList');
      if (choicesList) {
        choicesList.innerHTML = '';
        q.choices.forEach(ch => {
          const item = document.createElement('div');
          item.className = 'qcm-choice';
          item.id = `choice_${ch.id}`;
          item.onclick = () => toggleChoiceSelection(ch.id);
          item.innerHTML = `
            <div class="choice-badge">${ch.id}</div>
            <div class="choice-text-wrap">${ch.text}</div>
          `;
          choicesList.appendChild(item);
        });
      }

      const expBox = document.getElementById('qcmExplanationBox');
      if (expBox) expBox.style.display = 'none';

      const btnVal = document.getElementById('btnValidateQcm');
      if (btnVal) btnVal.style.display = 'inline-block';

      const btnNext = document.getElementById('btnNextQcm');
      if (btnNext) btnNext.style.display = 'none';
    }

    function toggleChoiceSelection(choiceId) {
      if (document.getElementById('btnNextQcm') && document.getElementById('btnNextQcm').style.display !== 'none') return;
      const el = document.getElementById(`choice_${choiceId}`);
      if (!el) return;
      if (userSelectedChoices.has(choiceId)) {
        userSelectedChoices.delete(choiceId);
        el.classList.remove('selected');
      } else {
        userSelectedChoices.add(choiceId);
        el.classList.add('selected');
      }
    }

    function validateCurrentQcm() {
      const list = getActiveQcmList();
      const q = list[currentQcmIndex];
      if (!q) return;

      const correctSet = new Set(q.correct_answers);

      let isPerfect = (userSelectedChoices.size === correctSet.size) &&
                      [...userSelectedChoices].every(x => correctSet.has(x));

      qcmAnsweredCount++;
      if (isPerfect) qcmScore++;

      const scoreEl = document.getElementById('qcmScoreDisplay');
      if (scoreEl) scoreEl.innerText = qcmScore;

      const ansEl = document.getElementById('qcmAnsweredDisplay');
      if (ansEl) ansEl.innerText = qcmAnsweredCount;

      q.choices.forEach(ch => {
        const el = document.getElementById(`choice_${ch.id}`);
        if (!el) return;
        const isCorrect = correctSet.has(ch.id);
        const wasSelected = userSelectedChoices.has(ch.id);

        if (isCorrect && wasSelected) {
          el.classList.add('correct');
        } else if (!isCorrect && wasSelected) {
          el.classList.add('incorrect');
        } else if (isCorrect && !wasSelected) {
          el.classList.add('missed');
        }
      });

      const expBox = document.getElementById('qcmExplanationBox');
      const expKey = document.getElementById('qcmExpKey');
      const expText = document.getElementById('qcmExpText');

      const corrStr = q.correct_answers.join(', ');
      if (expKey) {
        expKey.innerHTML = isPerfect
          ? `<span style="color: #065F46;">✅ Excellente réponse ! Clé officielle : ${corrStr}</span>`
          : `<span style="color: #DC2626;">❌ Erreur. Clé officielle : ${corrStr}</span>`;
      }

      if (expText) expText.innerText = q.explanation;
      if (expBox) expBox.style.display = 'block';

      const btnVal = document.getElementById('btnValidateQcm');
      if (btnVal) btnVal.style.display = 'none';

      const btnNext = document.getElementById('btnNextQcm');
      if (btnNext) btnNext.style.display = 'inline-flex';
    }

    function nextQcmQuestion() {
      currentQcmIndex++;
      renderCurrentQcm();
    }

    function renderQcmFinished() {
      const card = document.getElementById('qcmCardInner');
      const list = getActiveQcmList();
      const total = list.length;
      const pct = total > 0 ? Math.round((qcmScore / total) * 100) : 0;
      trackEvent('quiz_complete', {
        score: qcmScore,
        total: total,
        percentage: pct
      });
      if (card) {
        card.innerHTML = `
          <div style="background: var(--emerald-light); border: 1px solid var(--emerald-border); border-radius: 8px; padding: 24px; text-align: center;">
            <h3 style="font-family: var(--font-serif); font-size: 1.5rem; color: var(--emerald-dark); margin-bottom: 8px;">
              🎉 Test Terminé ! Score : ${qcmScore} / ${total} (${pct}%)
            </h3>
            <p style="font-size: 0.95rem; color: var(--ink-muted); max-width: 620px; margin: 0 auto 20px; line-height: 1.55;">
              Vous venez de vous entraîner sur des questions officielles des Collèges d'Enseignants universitaires. Accédez aux <strong>1 700+ QCMs d'annales</strong> et aux <strong>28 Référentiels complets</strong> dans le Pack Intégral EDN 2026.
            </p>
            <div style="display: flex; gap: 12px; justify-content: center; flex-wrap: wrap;">
              <a href="pack.html" class="btn-buy-grand-slam" style="width: auto; padding: 12px 28px; background: var(--emerald); text-decoration: none;">
                Découvrir le Pack Intégral (79 €)
              </a>
              <button onclick="restartQcmQuiz()" class="btn-card-primary" style="width: auto; background: #FFFFFF; color: var(--navy); border: 1px solid var(--border-dark);">
                Recommencer le Test
              </button>
            </div>
          </div>
        `;
      }
    }

    function restartQcmQuiz() {
      currentQcmIndex = 0;
      qcmScore = 0;
      qcmAnsweredCount = 0;
      document.getElementById('qcmScoreDisplay').innerText = 0;
      document.getElementById('qcmAnsweredDisplay').innerText = 0;
      renderCurrentQcm();
    }

    // =========================================================================
    // REAL MOZILLA PDF.JS WORKSTATION VIEWER
    // =========================================================================
    let currentPdfDoc = null;
    let currentPdfPage = 1;
    let currentPdfTotalPages = 1;
    let currentPdfScale = 1.35;
    let currentPdfRotation = 0;
    let isRenderingPdf = false;
    let pendingPdfPage = null;

    async function openPdfReader(url, title, subtitle, downloadUrl, buyUrl, isSample) {
      const modal = document.getElementById('pdfReaderModal');
      modal.classList.add('active');
      document.body.style.overflow = 'hidden';

      document.getElementById('pdfReaderTitle').innerText = title || 'Référentiel Médical Officiel';
      document.getElementById('pdfReaderSub').innerText = subtitle || "Collèges d'Enseignants Universitaires";

      const badge = document.getElementById('pdfReaderBadge');
      if (isSample) {
        badge.innerText = 'Extrait Officiel (6 pages)';
        badge.style.background = '#92400E';
        badge.style.color = '#FDE68A';
      } else {
        badge.innerText = 'Édition Complète Offerte';
        badge.style.background = '#065F46';
        badge.style.color = '#6EE7B7';
      }

      const dlBtn = document.getElementById('btnDownloadCurrentPdf');
      dlBtn.href = downloadUrl || url;
      dlBtn.style.display = downloadUrl ? 'inline-flex' : 'none';

      const buyBtn = document.getElementById('btnBuyCurrentPdf');
      buyBtn.href = buyUrl || 'https://edgettrading.gumroad.com/l/ycfkfa';

      currentPdfPage = 1;
      currentPdfRotation = 0;
      currentPdfScale = window.innerWidth < 768 ? 0.85 : 1.35;
      updateZoomDisplay();

      showPdfSpinner(true);
      try {
        if (!window.pdfjsLib) throw new Error('PDF.js non disponible');
        const loadingTask = pdfjsLib.getDocument(url);
        currentPdfDoc = await loadingTask.promise;
        currentPdfTotalPages = currentPdfDoc.numPages;

        document.getElementById('pdfPageTotal').innerText = currentPdfTotalPages;
        document.getElementById('pdfSidebarCount').innerText = `${currentPdfTotalPages} p.`;
        document.getElementById('pdfPageInput').max = currentPdfTotalPages;

        buildPdfThumbnails(currentPdfTotalPages);
        await renderPdfPage(1);
      } catch (err) {
        console.error('Erreur ouverture PDF:', err);
        window.open(url, '_blank');
        closePdfReader();
      } finally {
        showPdfSpinner(false);
      }

      window.addEventListener('keydown', handlePdfKeydown);
    }

    function closePdfReader() {
      const modal = document.getElementById('pdfReaderModal');
      modal.classList.remove('active');
      document.body.style.overflow = '';
      window.removeEventListener('keydown', handlePdfKeydown);
      currentPdfDoc = null;
    }

    function showPdfSpinner(show) {
      const sp = document.getElementById('pdfSpinnerOverlay');
      if (sp) sp.style.display = show ? 'flex' : 'none';
    }

    async function renderPdfPage(num) {
      if (!currentPdfDoc) return;
      isRenderingPdf = true;
      currentPdfPage = num;

      document.getElementById('pdfPageInput').value = num;
      document.getElementById('btnPrevPage').disabled = num <= 1;
      document.getElementById('btnNextPage').disabled = num >= currentPdfTotalPages;

      highlightActiveThumbnail(num);

      try {
        const page = await currentPdfDoc.getPage(num);
        const canvas = document.getElementById('pdfRenderCanvas');
        const ctx = canvas.getContext('2d');

        const viewport = page.getViewport({ scale: currentPdfScale, rotation: currentPdfRotation });
        const outputScale = window.devicePixelRatio || 1;

        canvas.width = Math.floor(viewport.width * outputScale);
        canvas.height = Math.floor(viewport.height * outputScale);
        canvas.style.width = Math.floor(viewport.width) + 'px';
        canvas.style.height = Math.floor(viewport.height) + 'px';

        const transform = outputScale !== 1 ? [outputScale, 0, 0, outputScale, 0, 0] : null;

        await page.render({
          canvasContext: ctx,
          transform: transform,
          viewport: viewport
        }).promise;
      } catch (e) {
        console.warn('Rendu page:', e);
      } finally {
        isRenderingPdf = false;
        if (pendingPdfPage !== null) {
          const p = pendingPdfPage;
          pendingPdfPage = null;
          renderPdfPage(p);
        }
      }
    }

    function queueRenderPdf(num) {
      if (isRenderingPdf) pendingPdfPage = num;
      else renderPdfPage(num);
    }

    function prevPdfPage() {
      if (currentPdfPage <= 1) return;
      queueRenderPdf(currentPdfPage - 1);
    }

    function nextPdfPage() {
      if (currentPdfPage >= currentPdfTotalPages) return;
      queueRenderPdf(currentPdfPage + 1);
    }

    function goToPdfPage(val) {
      let n = parseInt(val, 10);
      if (isNaN(n)) n = 1;
      n = Math.max(1, Math.min(n, currentPdfTotalPages));
      queueRenderPdf(n);
    }

    function zoomPdf(delta) {
      let s = currentPdfScale + delta;
      s = Math.max(0.5, Math.min(s, 3.0));
      currentPdfScale = Math.round(s * 100) / 100;
      updateZoomDisplay();
      queueRenderPdf(currentPdfPage);
    }

    function fitPdfWidth() {
      const vpEl = document.getElementById('pdfViewport');
      const availWidth = vpEl.clientWidth - 48;
      if (!currentPdfDoc || availWidth <= 0) return;
      currentPdfDoc.getPage(currentPdfPage).then(page => {
        const vp = page.getViewport({ scale: 1.0, rotation: currentPdfRotation });
        currentPdfScale = Math.round((availWidth / vp.width) * 100) / 100;
        updateZoomDisplay();
        queueRenderPdf(currentPdfPage);
      });
    }

    function rotatePdf() {
      currentPdfRotation = (currentPdfRotation + 90) % 360;
      queueRenderPdf(currentPdfPage);
    }

    function updateZoomDisplay() {
      document.getElementById('pdfZoomLabel').innerText = `${Math.round(currentPdfScale * 100)}%`;
    }

    function togglePdfSidebar() {
      document.getElementById('pdfReaderSidebar').classList.toggle('collapsed');
    }

    function togglePdfFullscreen() {
      const m = document.getElementById('pdfReaderModal');
      if (!document.fullscreenElement) m.requestFullscreen().catch(() => {});
      else document.exitFullscreen().catch(() => {});
    }

    function buildPdfThumbnails(total) {
      const scroll = document.getElementById('pdfThumbnailsScroll');
      scroll.innerHTML = '';
      const limit = Math.min(total, 60);
      for (let i = 1; i <= limit; i++) {
        const card = document.createElement('div');
        card.className = `pdf-thumb-card ${i === 1 ? 'active' : ''}`;
        card.id = `thumbCard_${i}`;
        card.onclick = () => queueRenderPdf(i);
        card.innerHTML = `
          <span class="pdf-thumb-num">Page ${i}</span>
          <svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M9 5l7 7-7 7"/></svg>
        `;
        scroll.appendChild(card);
      }
    }

    function highlightActiveThumbnail(num) {
      const prev = document.querySelector('.pdf-thumb-card.active');
      if (prev) prev.classList.remove('active');
      const cur = document.getElementById(`thumbCard_${num}`);
      if (cur) {
        cur.classList.add('active');
        cur.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
      }
    }

    function handlePdfKeydown(e) {
      if (e.key === 'Escape') closePdfReader();
      else if (e.key === 'ArrowRight' || e.key === 'PageDown') nextPdfPage();
      else if (e.key === 'ArrowLeft' || e.key === 'PageUp') prevPdfPage();
      else if (e.key === '+' || e.key === '=') zoomPdf(0.2);
      else if (e.key === '-') zoomPdf(-0.2);
      else if (e.key.toLowerCase() === 'f') togglePdfFullscreen();
      else if (e.key.toLowerCase() === 'r') rotatePdf();
    }

    // Open Book in PDF Reader
    function openBookPdf(num) {
      const b = booksData.find(x => x.n === num);
      if (!b) return;

      if (num === 1) {
        openPdfReader(
          'EDN-Tome-01-LCA-Offert.pdf',
          'Tome 01 — LCA (Lecture Critique d\'Article)',
          '270 pages · Volume Complet Offert · Conforme R2C',
          'EDN-Tome-01-LCA-Offert.pdf',
          'https://edgettrading.gumroad.com/l/ycfkfa',
          false
        );
      } else if (num === 2) {
        openPdfReader(
          'EDN-Tome-02-Neurologie-Offert.pdf',
          'Tome 02 — Neurologie R2C Complète',
          '657 pages · 872 Tableaux Cliniques · Volume Complet Offert',
          'EDN-Tome-02-Neurologie-Offert.pdf',
          'https://edgettrading.gumroad.com/l/ycfkfa',
          false
        );
      } else {
        const previewUrl = b.preview_pdf || `previews/preview-${num < 10 ? '0' + num : num}.pdf`;
        openPdfReader(
          previewUrl,
          `Tome ${num < 10 ? '0' + num : num} — ${b.title}`,
          `${b.pages} pages · ${b.college} · R2C 2026`,
          null,
          b.gumroad_url ? `https://edgettrading.gumroad.com/l/${b.gumroad_url}` : 'https://edgettrading.gumroad.com/l/ycfkfa',
          true
        );
      }
    }

    // =========================================================================
    // FAQ & STICKY BAR CONTROLS
    // =========================================================================
    function toggleFaq(el) {
      const item = el.parentElement;
      item.classList.toggle('active');
    }

    let isStickyDismissed = false;
    function dismissStickyBar() {
      isStickyDismissed = true;
      document.getElementById('stickyBottomBar').classList.remove('visible');
    }

    window.addEventListener('scroll', () => {
      if (isStickyDismissed) return;
      const bar = document.getElementById('stickyBottomBar');
      if (window.scrollY > 750) {
        bar.classList.add('visible');
      } else {
        bar.classList.remove('visible');
      }
    });


    // =========================================================================
    // MOBILE DRAWER CONTROLS (< 768px)
    // =========================================================================
    function openMobileDrawer() {
      const drawer = document.getElementById('mobileDrawer');
      const backdrop = document.getElementById('mobileDrawerBackdrop');
      const toggle = document.getElementById('mobileMenuToggle');
      if (drawer && backdrop) {
        drawer.classList.add('active');
        backdrop.classList.add('active');
        document.body.style.overflow = 'hidden';
        if (toggle) toggle.setAttribute('aria-expanded', 'true');
      }
    }

    function closeMobileDrawer() {
      const drawer = document.getElementById('mobileDrawer');
      const backdrop = document.getElementById('mobileDrawerBackdrop');
      const toggle = document.getElementById('mobileMenuToggle');
      if (drawer && backdrop) {
        drawer.classList.remove('active');
        backdrop.classList.remove('active');
        document.body.style.overflow = '';
        if (toggle) toggle.setAttribute('aria-expanded', 'false');
      }
    }

    function toggleMobileDrawer() {
      const drawer = document.getElementById('mobileDrawer');
      if (drawer && drawer.classList.contains('active')) {
        closeMobileDrawer();
      } else {
        openMobileDrawer();
      }
    }

    // =========================================================================
    // INLINE NEWSLETTER EMAIL CAPTURE
    // =========================================================================
    function handleNewsletterSubmit(e) {
      if (e) e.preventDefault();
      const input = document.getElementById('newsletterEmailInput');
      const form = document.getElementById('newsletterForm');
      const feedback = document.getElementById('newsletterFeedback');
      if (!input || !form) return;

      const email = input.value.trim();
      if (!email || !email.includes('@')) {
        alert('Veuillez renseigner une adresse e-mail valide.');
        return;
      }

      try {
        localStorage.setItem('edn_newsletter_email', email);
      } catch (err) {}

      trackEvent('generate_lead', {
        method: 'inline_newsletter',
        email: email
      });

      form.style.display = 'none';
      if (feedback) {
        feedback.innerHTML = `
          <div class="email-success-badge">
            <svg width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.5" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M5 13l4 4L19 7"/></svg>
            <span>Merci ! Votre premier cas clinique a été envoyé. Consultez votre boîte mail d'ici quelques minutes.</span>
          </div>
        `;
        feedback.style.display = 'block';
      }
    }

    // =========================================================================
    // EXIT-INTENT MODAL POPUP
    // =========================================================================
    let exitModalTriggered = false;

    function showExitModal() {
      if (exitModalTriggered) return;
      if (sessionStorage.getItem('exitModalShown')) return;

      const modal = document.getElementById('exitModalBackdrop');
      if (!modal) return;

      exitModalTriggered = true;
      sessionStorage.setItem('exitModalShown', 'true');
      modal.classList.add('active');
    }

    function closeExitModal() {
      const modal = document.getElementById('exitModalBackdrop');
      if (modal) {
        modal.classList.remove('active');
      }
    }

    // Exit intent triggers when cursor leaves top viewport (e.clientY <= 0)
    document.addEventListener('mouseleave', (e) => {
      if (e.clientY <= 0) {
        showExitModal();
      }
    });

    // =========================================================================
    // INITIALIZATION & EVENT LISTENERS
    // =========================================================================
    document.addEventListener('DOMContentLoaded', () => {
      renderCatalog();
      renderCurrentQcm();

      // Newsletter form listener
      const newsForm = document.getElementById('newsletterForm');
      if (newsForm) {
        newsForm.addEventListener('submit', handleNewsletterSubmit);
      }

      // Check localStorage for saved email
      try {
        const savedEmail = localStorage.getItem('edn_newsletter_email');
        if (savedEmail) {
          const input = document.getElementById('newsletterEmailInput');
          if (input && !input.value) input.value = savedEmail;
        }
      } catch (err) {}

      // Global Escape listener for modals and drawer
      document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
          closeExitModal();
          closeMobileDrawer();
        }
      });
    });
